package cli

import (
	"bufio"
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math"
	"os"
	"path/filepath"
	"runtime/debug"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/entireio/entire-brain/internal/cli/entities"
	"github.com/entireio/entire-brain/internal/cli/internal/base"
	workspacelib "github.com/entireio/entire-brain/internal/cli/workspace"
	"github.com/spf13/cobra"
)

const maxMCPFrameBytes = 4 * 1024 * 1024

var mcpRefreshTimeout = 60 * time.Second

// mcpIndexTimeout bounds brain_index_repository. brain_refresh has been capped
// since it was written, and index is the same shape of work — a full provider
// snapshot over a repository of unknown size — on the same stdio transport,
// where a call that never returns is a client that never recovers. The tool
// descriptions already advertised the asymmetry: brain_refresh's says "Calls
// are capped at 60 seconds", index's said nothing.
var mcpIndexTimeout = 60 * time.Second

type mcpFrameMode string

const (
	mcpFrameContentLength mcpFrameMode = "content-length"
	mcpFrameJSONLine      mcpFrameMode = "json-line"
)

type mcpMessage struct {
	JSONRPC string          `json:"jsonrpc"`
	ID      any             `json:"id,omitempty"`
	Method  string          `json:"method,omitempty"`
	Params  json.RawMessage `json:"params,omitempty"`
	Result  any             `json:"result,omitempty"`
	Error   *mcpError       `json:"error,omitempty"`
}

type mcpError struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
}

type mcpToolCallParams struct {
	Name      string         `json:"name"`
	Arguments map[string]any `json:"arguments"`
}

// mcpInvalidParamsError marks a tool failure the CALLER can fix by sending
// different arguments, so the JSON-RPC reply can carry -32602 ("Invalid
// params") instead of the -32000 every failure used to share.
//
// Every failure on this surface was -32000: a limit of 99999, an unknown
// argument name, a missing required field, and a genuine execution failure were
// indistinguishable to a client. -32602 is the code JSON-RPC reserves for
// exactly the first three, and MCP's own tool guidance uses it for an unknown
// tool name. Splitting only the argument half is deliberate:
//
//   - Validation errors move to -32602. A client that switches on the code now
//     learns "do not retry this call as written"; one that does not switch on
//     the code is unaffected, because the message is unchanged and both codes
//     are errors.
//   - EXECUTION failures deliberately stay a JSON-RPC error rather than moving
//     into the result as isError:true, which is what MCP prefers. Moving them
//     would turn every existing client's error path into a success path, and a
//     client that does not read isError would then treat a failed call as a
//     successful one. That is a silent-wrong-answer regression traded for spec
//     tidiness, so it is left alone and reported instead.
type mcpInvalidParamsError struct{ err error }

func (e *mcpInvalidParamsError) Error() string { return e.err.Error() }
func (e *mcpInvalidParamsError) Unwrap() error { return e.err }

// mcpInvalidParams builds an argument-validation failure.
func mcpInvalidParams(format string, args ...any) error {
	return &mcpInvalidParamsError{err: fmt.Errorf(format, args...)}
}

// mcpRequiredArg is the one phrasing for a missing required argument.
func mcpRequiredArg(name string) error { return mcpInvalidParams("%s is required", name) }

// mcpToolNamesHint names where a caller finds the legal values, without
// inlining thirty-six names into one error message.
func mcpToolNamesHint() string {
	return fmt.Sprintf("call tools/list for the %d available tools", len(mcpToolDefinitions()))
}

// mcpErrorCodeFor picks the JSON-RPC code for a tools/call failure.
func mcpErrorCodeFor(err error) int {
	var invalid *mcpInvalidParamsError
	if errors.As(err, &invalid) {
		return -32602
	}
	return -32000
}

type mcpResponseTransport struct {
	ID        any
	FrameMode mcpFrameMode
}

type mcpResponseTransportContextKey struct{}

func newMCPCommand(opts Options) *cobra.Command {
	var (
		printConfig bool
		httpAddr    string
		allowRemote bool
	)
	cmd := &cobra.Command{
		Use:   "mcp",
		Short: "Serve local brain tools over MCP (stdio by default, or HTTP with --http)",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			if printConfig {
				return printMCPServerConfig(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), opts)
			}
			nudgeMemoryAtStartup(cmd.Context(), opts)
			if strings.TrimSpace(httpAddr) != "" {
				return runMCPHTTP(cmd.Context(), cmd.OutOrStdout(), opts, httpAddr, allowRemote)
			}
			return runMCP(cmd.Context(), cmd.InOrStdin(), cmd.OutOrStdout(), opts)
		},
	}
	cmd.Flags().BoolVar(&printConfig, "print-config", false,
		"Print an MCP server entry that launches this binary directly, for a host agent's config")
	// Absent by default: with no --http there is no listener and no network,
	// which is what SECURITY.md promises about the default build.
	cmd.Flags().StringVar(&httpAddr, "http", "",
		"Also serve MCP over HTTP on this address (e.g. 127.0.0.1:7777). A bare port binds loopback. Always requires a bearer token")
	cmd.Flags().BoolVar(&allowRemote, "http-allow-remote", false,
		"Permit --http to bind a non-loopback address. The brain holds source, transcripts and prompts; put TLS in front of it")
	return cmd
}

// mcpServerName is the key host agents register this server under.
const mcpServerName = "entire-brain"

// printMCPServerConfig writes an MCP server entry naming this executable by
// absolute path.
//
// Hosts are usually registered with `entire brain mcp`, which asks the Entire
// CLI to resolve `brain` as a plugin at spawn time. That resolution depends on
// which entire is first on PATH and on the environment the host spawns with; it
// resolves HOME to find the plugin, so a spawn without it exits with
//
//	Error: Invalid usage: unknown command "brain" for "entire"
//
// and the host surfaces only CONNECTION_CLOSED -- which names neither the
// command nor the cause, and is why this was hard to diagnose from the agent
// side. Naming this binary directly removes the lookup, so the entry keeps
// working regardless of PATH order or spawn environment.
//
// The entry also BINDS THE SERVER to a repository via ENTIRE_REPO_ROOT. It used
// to emit an empty env, and an empty env is not a neutral default: a server with
// no bound repository refuses every repo-scoped tool (brain_list_projects,
// brain_delete_project, and the three brain_workspace_* tools), so the config
// this command recommends advertised 36 tools of which 5 could never succeed.
// A host registering the printed entry verbatim is entitled to the whole
// surface.
//
// The entry also CARRIES THE STORE, for the same reason it carries the binding:
// two of the three harnesses that consume it do not give the server the
// environment the command was printed in. Codex starts an MCP server with a
// 14-variable allowlist and Cursor with a 15-variable one -- HOME, PATH, PWD,
// SHELL, USER and friends -- plus whatever the entry's own `env` block declares;
// only Claude Code passes the parent environment through. Every ENTIRE_* and
// XDG_* variable is therefore dropped unless it is written into the entry. The
// four plugin dirs are what resolvePluginDirs reads to find the brain, so an
// entry that omits them leaves the server to re-derive a store from an
// environment that no longer has the inputs -- and it lands on the default
// $HOME/.local/share/entire path. The CLI and the agent then read DIFFERENT
// BRAINS for the same repository, and the agent is told "no brain has been built
// for this repository": a confident wrong answer, not an error. Emitting the
// resolved dirs is exact, not merely close -- resolveXDGDir returns an explicit
// plugin dir verbatim, and resolvePluginDirs only appends the plugins/data/brain
// suffix when the data dir was unset -- so the printed entry round-trips to the
// same paths this process is using.
func printMCPServerConfig(ctx context.Context, out, errOut io.Writer, opts Options) error {
	executable, err := os.Executable()
	if err != nil {
		return fmt.Errorf("resolve this executable: %w", err)
	}
	env := map[string]string{}
	if root := mcpConfigRepoRoot(ctx, opts); root != "" {
		env[envRepoRoot] = root
	} else if errOut != nil {
		// SAY SO. Without a binding the entry is still usable -- 31 of the 36
		// tools resolve their target from the server's working directory -- but
		// the five repo-scoped ones refuse, and the printed JSON says nothing
		// about it. The note goes to stderr so `--print-config > .mcp.json`
		// keeps working.
		fmt.Fprintf(errOut, "note: printed an entry with no %s binding: %s\n"+
			"      brain_list_projects, brain_delete_project and the three brain_workspace_* tools "+
			"refuse on a server that is neither bound nor started inside a repository.\n",
			envRepoRoot, mcpConfigNoBindingReason(ctx, opts))
	}
	for name, dir := range mcpConfigStoreEnv(opts) {
		env[name] = dir
	}
	// Deliberately not resolved through symlinks: the managed install path is
	// the stable one, while its target moves whenever the plugin is rebuilt.
	config := map[string]any{
		"mcpServers": map[string]any{
			mcpServerName: map[string]any{
				"type":    "stdio",
				"command": executable,
				"args":    []string{"mcp"},
				"env":     env,
			},
		},
	}
	encoded, err := json.MarshalIndent(config, "", "  ")
	if err != nil {
		return fmt.Errorf("encode MCP server config: %w", err)
	}
	_, err = fmt.Fprintln(out, string(encoded))
	return err
}

// mcpConfigStoreEnv is the store binding the printed entry carries so a host
// that prunes the environment still reaches the brain this process reads.
//
// The values are the RESOLVED dirs, not the raw variables, because the raw
// variables are not the whole input: XDG_CONFIG_HOME and friends feed
// resolveXDGDir, and Codex and Cursor drop those too. Resolving here collapses
// every input into four absolute paths that need no environment to reproduce.
//
// A resolution failure emits nothing. That is the pre-existing behaviour -- an
// entry with no store dirs -- and it is strictly better than writing a path this
// process could not itself resolve.
func mcpConfigStoreEnv(opts Options) map[string]string {
	dirs, err := resolvePluginDirs(opts.Env)
	if err != nil {
		return nil
	}
	return map[string]string{
		envPluginConfigDir: dirs.Config,
		envPluginDataDir:   dirs.Data,
		envPluginStateDir:  dirs.State,
		envPluginCacheDir:  dirs.Cache,
	}
}

// mcpConfigNoBindingReason names why --print-config had no repository to bind,

package cli

import (
	"context"
	"crypto/rand"
	"crypto/subtle"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strings"
	"syscall"
	"time"

	"github.com/entireio/entire-brain/internal/tui"
)

// MCP over HTTP.
//
// `brain mcp` speaks stdio, which means the only thing that can reach a brain
// is a process the user launched on the same machine. That is a real limit: a
// teammate, a second machine, or an agent running anywhere else simply cannot
// query it. mem0, cognee and supermemory all expose remote MCP.
//
// It is also the most dangerous gap on the list to close, and the design says
// so throughout. A brain holds repository source, agent transcripts, prompts
// and commit history. An HTTP endpoint in front of that is a door, and the
// whole question is who gets to walk through it. So:
//
//   - It does not exist unless asked for. No flag, no listener. `brain mcp`
//     keeps speaking stdio and keeps making no network calls, which is what
//     SECURITY.md promises.
//   - It binds loopback unless explicitly told otherwise. A bare port means
//     127.0.0.1, never 0.0.0.0 — the difference between "my other terminal"
//     and "everyone on the coffee shop wifi" should not be a default.
//   - It always requires a bearer token. There is no unauthenticated mode, not
//     even on loopback: every process on the machine shares loopback, and
//     "localhost is safe" is how a brain gets read by a browser tab.
//   - Reaching a non-loopback interface needs a second, separate flag. Two
//     deliberate acts, because that one is genuinely different in kind.
//
// The handler reuses handleMCPMessage, the same dispatch stdio uses, so the two
// transports cannot drift apart in what they expose.

const (
	mcpHTTPTokenEnv = "ENTIRE_BRAIN_MCP_TOKEN"
	// Requests are bounded: an MCP message is small, and an unbounded body on a
	// local daemon is a trivial way to exhaust memory.
	mcpHTTPMaxBodyBytes = 4 << 20
	mcpHTTPReadTimeout  = 30 * time.Second
	mcpHTTPWriteTimeout = 120 * time.Second
	mcpHTTPIdleTimeout  = 90 * time.Second
)

