	content, ok := result["content"].([]map[string]any)
	if !ok || len(content) != 1 {
		t.Fatalf("brain_brief MCP content = %#v", result["content"])
	}
	text, ok := content[0]["text"].(string)
	if !ok {
		t.Fatalf("brain_brief MCP text = %#v", content[0]["text"])
	}
	return text
}
